from heapq import heapify, heappop, heappush

def influence_leaderboard(n, m, scores, requirements):
    opCount = 0
    # Initialize a min heap to keep track of the top scores
    top_scores = []
    # Initialize a max heap to keep track of the bottom scores
    bottom_scores = []
    for i in range(n):
        if scores[i] <= requirements[i][0]:
            heappush(bottom_scores, -scores[i])
        else:
            top_scores.append(-scores[i])

    # Perform the operations
    for _ in range(m):
        u, v = requirements.pop()
        if u < v:
            while scores[u] > bottom_scores[0]:
                score = -heappop(bottom_scores)
                heappush(top_scores, -score)
            while scores[u] < scores[v]:
                heappush(bottom_scores, -heappop(top_scores))
            opCount += 1
        elif u > v and scores[u] > requirements[u][0]:
            while scores[v] <= top_scores[0]:
                score = -heappop(top_scores)
                heappush(bottom_scores, score)
            while scores[v] > scores[u]:
                heappush(bottom_scores, heappop(top_scores))
            opCount += 1
    # Ensure all values are within the [-10^15, 10^15] range
    for score in scores:
        if score < 0:
            score = -min(opCount, score-(-1))
        elif score > 0:
            score = -max(opCount, -score-(-1))
        scores[scores.index(score)] = score

    return scores

