from collections import defaultdict
from typing import List, Tuple

def lex_min_code(words: List[str], syms: str, rules: List[Tuple[int, str, int, str]]) -> str:
    letter_size = len(syms)
    letter_order = 'V' + syms + 'VC'

    if letter_size == 1:
        return ' '.join(words)

    word_map = defaultdict(list)
    for i, c in enumerate('V' + syms + 'VC', 1):
        word_map[c].append(i)

    def better_word(w) -> bool:
        i = 1
        while i < len(w) - 1 and w[i] != ' ': i += 1
        while i < len(w) - 1 and w[i] == ' ': i += 1
        part = w[:i]
        x, y = word_map[part]
        if x == -1: return False
        l = 0
        while x + l < len(w) and y - l == 0: l += 1
        return l == 1 and (w[x] in rules)

    word_lowers = [word for word in words]
    i = 0
    while i < len(word_lowers) and better_word(word_lowers[i]):
        i += 1
    if i == len(word_lowers): return '-1'

    lowers_to_idx = {l: i for i, l in enumerate(word_lowers)}
    # Index is -1 if no lower word
    for i in range(i):
        l_lower = word_lowers[lowers_to_idx[i]]
        l_lower_letters = set(l_lower[:i+1])
        ones = defaultdict(list)
        for diff, w_upper in enumerate(word_lowers[lowers_to_idx[i+1:]]):
            for letter in set(w_upper[:i+1]):
                if letter in l_lower: continue
                ones[(l_lower_letters - {letter}).difference(w_upper[:j for j, w in enumerate(w_upper) if w == letter])].append(diff)
        for h in range(letter_size):
            if h in l_lower_letters: continue
            if h in ones and pred := ones[h]: 
                i = min(pred)
    return ''.join([letter_order[w[0]]*w[1] for w in sorted(list(enumerate(words)), key=lambda x: (-len(x[1]), x[1]))])
