class Mst:
    def __init__(self, parent):
        self.parent = parent

    def find(self):
        if self.parent != self:
            self.parent = find(self.parent)
        return self.parent

def union(node1, node2):
    par1 = find(node1)
    par2 = find(node2)
    if par1 != par2:
        find(node1) = par2

def min_spanning_tree(parent):
    mst = Mst(parent)
    edges = []
    result = []
    for i in range(1, len(parent)):
        edges.append((i, find(i), find(i+i), True))
        edges.append((i, find(i), i+i, False))
    heapq.heapify(edges)
    num_factors = len(parent)
    while len(edges) > 0:
