from collections import defaultdict

def find_parent(parent, key):
    if parent[key] == key:
        return key
    return find_parent(parent, parent[key])

def union(parent, rank, x, y):
    rootX = find_parent(parent, x)
    rootY = find_parent(parent, y)
    if rootX != rootY:
        if rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        elif rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def count_components(m, elements):
    parent = defaultdict(int)
    rank = defaultdict(int)
    for element in elements:
        parent[element] = element
        rank[element] = 0

    components = 0
    for i in range(m):
        for j in range(i + 1, m):
            if (elements[i] & elements[j]) == 0:
                union(parent, rank, elements[i], elements[j])

        connected = True
        for elem in elements:
            parent[elem] = elem
            rank[elem] = 0
            for j in range(i + 1, m):
                if (elem & elements[j]) == 0:
                    connected = False
                    break
            if connected:
                components += 1
                break
    return components

