def count_trees(n, max_weight, a, b):
    states = [0] * (n + 1)
    mod = 10**9 + 7

    def next_state(current):
        if states[current] == 0:
            states[current] = (current * (current - 1) // 2) % mod
        return (current * ((current - 2) * (current - 1) // 2) % mod + states[current]) % mod

    def is_beautiful(trees):
        blossom = (a - 1) * (max_weight - b) + b * (a - 1) + (a - 1)
        discounted = reduce(lcm, trees)
        discount = len(trees) - 1
        for i in range(discount):
            if sum(map(lambda x: trees[x] % discount == tree % discount, range(discount))) - 2 * (sum(trees[:i + 1]) % discount) == discount - 1:
                return True
        blossom -= sum(map(lambda x: 2 * (trees[x] % discount), range(discount)))
        return blossom < 0

    leaves = [a - 1]
    for i in range(2, n - 2):
        x = b + 1
        while x <= max_weight:
            if x - 1 not in leaves[-1:0:-1]:
                leaves.append(x - 1)
            x *= 2
    leaves.sort()
    trees = [reduce(lcm, [leaf, discount + 1]) for leaf in leaves]

    states = [0]
    fld = 0
    for current in accumulate(trees):
        states = [states[1] + (current - states[0] + 1) % mod] + states[1:]
        if current == 0:
            fld = next_state(current)

    all_states = list(map(lambda x: 1, range(1, n)))
    real_states = list(filter(lambda x: x != 0, states))
    result = reduce(lcm, set(reduce(map, zip(map(lambda x: x[0], states), states))), 1)

    total_trees = 1
    for prod in range(2, max_weight + 1):
        tree = reduce(lcm, [prod, max_weight + 2])
        if is_beautiful(set(accumulate(trees, lambda x, y: x + tree * y)))[0] == prod * (prod + 1) // 2 % mod:
            total_trees *= real_states[prod]

    real_leaves = set(accumulate(trees))
    for other_weight in range(1, max_weight + 1):
        to_append = next_state(max_weight + 2)
        while to_append in real_leaves:
            to_append *= sum(map(lambda x: 1, range(1, other_weight + 1)))
        total_trees *= to_append

    return fld * total_trees % mod


