def count_unique_chars(strings, position, alphabet):
    count = defaultdict(int)
    for string in strings:
        count[string[position]] += 1
    return len(count)

def min_cost(n, m, strings, costs):
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i][j - 1] + min(costs[i-1][j-1], dp[i-1][j-1])
            if count_unique_chars(strings, j-1, alphabet) == 1:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] - costs[i-1][j-1])
