def get_orbits(n: int, m: int, a: List[int]) -> int:
    tree = defaultdict(list)
    mark = defaultdict(int)

    def dfs(node: int):
        mark[node] = 1
        for child in tree[node]:
            if not mark[child]:
                dfs(child)

    for i in range(m):
        x = a[i]
        level = 0
        while x:
            level = max(level, level.bitcount() // 2)
            x &= (x - 1)

        if level == 0:
            mark[x] = 1
            for child in tree[x]:
                if not mark[child] and child != x:
                    dfs(child)
        else:
            tree[level].append(x)

    return len(tree) - sum([1 for k, v in mark.items() if v and v != 2**(n)//2])

