def compute_answer(N, edges, queries):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dfs(node, parent, level):
        dist[node] = level
        for child, weight in graph[node]:
            if child != parent:
                dfs(child, node, level + weight)

    dist = [0] * (N + 1)  # Initialize distances for each vertex
    dfs(1, 0, 0)  # Start DFS from the first vertex

    def calculate_path_distance(node, k):
        return dist[node] - dist[k]

    def calculate_answer(x, y):
        total = 0
        for u, v, w in edges:
            if u < N and dist[u] <= dist[v] or v < N and dist[v] <= dist[u]:
                continue
            if dist[u] <= dist[v]:  # Weighted case
                total += w * (calculate_path_distance(x, u) - calculate_path_distance(u, y))
            else:  # Non-weighted case
                total += (calculate_path_distance(x, u) - calculate_path_distance(u, y)) * A[u]
        return total

    for x, y in queries:
        print(calculate_answer(x, y))

