from functools import lru_cache
from math import inf

def total_expenses(strings: List[str], changes: List[List[int]]) -> int:
    n, m = len(strings), len(strings[0])

    @lru_cache(None)
    def dp(index: int, prev_symbol: str, total_slots: int) -> int:
        if index == n:
            return 0

        min_cost = inf
        for slot in range(m):
            current_symbol = strings[index][slot]
            if slot != prev_symbol:
                good_changes = {c for c in current_symbol if c != prev_symbol}
                bad_changes = {c for c in current_symbol if c == prev_symbol}

                for change in good_changes:
                    min_cost = min(min_cost, change * changes[index][slot] + dp(index + 1, change, total_slots))

                for bad_change in bad_changes:
                    min_cost = min(min_cost, total_slots * changes[index][slot] + dp(index + 1, bad_change, total_slots - 1))

        return min_cost

    return dp(0, -1, m)

