import collections

def minimize_operations(n, m, scores, requirements):
    left_tree = collections.defaultdict(list)
    right_tree = collections.defaultdict(list)

    # Build subtrees from left to right
    for u, v in requirements:
        if u != v:
            left_tree[u].append(v)
            right_tree[v].append(u)

    prefix_sums, previous_sums, solution = {}, {}, []
    build_down_stack()

    for v, scores_of_v in scores.items():
        solution[v] = v if v not in previous_sums else previous_sums[v]
        update_sums(v)

    update_sums(1)
    for u in range(1, n + 1):
        solution[u] = solution[u] + scores[u]
        update_sums(u)

    def update_sums(parent):
        prefix_sum = solution[parent]
        solution[parent] += sum(scores[child] for child in left_tree[parent])
        solution[parent] = max(solution[parent], prefix_sum)
        solution[parent] -= sum(scores[child] for child in right_tree[parent])

    def build_down_stack():
        visited, stack = {}, []
        for v in range(1, n + 1):
            if v not in visited and len(right_tree[v]) == 0:
                visited[v] = current_down
                for child in left_tree[v]:
                    stack.append(child)
        while stack:
            v = stack.pop()
            for child in left_tree[v]:
                visited[child] = current_down
                for child_prime in left_tree[child]:
                    stack.append(child_prime)
            for child in right_tree[v]:
                current_down = child
                for child_prime in left_tree[child]:
                    stack.append(child_prime)
            for child in right_tree[v]:
                solution[child] = current_down
                solution[child] += scores[child]
                update_sums(child)

    while len(solution) < n + 1:
        parent = 1
        smallest = float('inf')
        for v in range(1, n + 1):
            if v in solution and v not in left_tree:
                if solution[v] < smallest:
                    smallest = solution[v]
                    parent = v
        if smallest == float('inf'):
            break
        solution[parent] += 1
        update_sums(parent)
        if parent not in left_tree:
            for child in left_tree.values():
                if len(child) == 1:
                    solution[child[0]] = solution[parent] - scores[child[0]]
                    update_sums(child[0])
                    break
                left_down = solution[child[0]]
                for child_prime in left_tree[child[0]]:
                    left_down = min(left_down, solution[child_prime])
                    solution[child] = solution[parent] - left_down
                    update_sums(child)
                    break

