    for depot in range(1, n):
        grouped, min_distance = {}, float('inf')

        for city, distance in distances.copy():
            if distance < min_distance:
                min_distance, grouped = distance, {city}

            elif distance == min_distance:
                grouped.add(city)

        distances[grouped.pop(0)] = min_distance + 1

        for city in grouped:
            graph[city] = [(route, distance+distances[depot][city]+k) if route else (route, 0) for route in graph[city] if route]

    result = [None] * n
    visited = [[] for _ in range(n)]

    for i in range(n):
        cost = float('inf')
        next_node = None

        for city, (route, cost) in sorted(graph[i], key=lambda x: (x[0], distances[i]) if x[0] != i else (x[1], distances[i])):
            if route not in visited[i]:
                visited[i].append(route)

                if len(visited[i]) > 1:
                    next_cost = cost + sum(min_dist + 2 * k if min_dist else min_dist + k for (min_dist, _), route in graph[route])
                    if cost > next_cost:
                        next_node = i
                        cost = next_cost

        visited[i].append(next_node)
        result[i] = next_node

    return sum(computation[i] for i in range(n) if computation[i][0] == 0), '\n'.joinmap(str(computation[i][1]+1 for i in range(n)) for computation in tuple(dijkstra(i, (city for city in range(n))))), (n, n, result)

def usage():
    print("Usage: min_maintenance_costs(n, k, distances, roads)")

def run():
    n, k = map(int, input().split())
    distances = list(map(int, input().split()))
    roads = [tuple(map(int, road.split())) for road in input().split()]

    min_maintenance_costs(n, k, distances, roads)
